select date_trunc('MONTH', store_sales.sale_date) as sale_month, store_sales.product_id, max(inventory.quantity) - min(inventory.quantity) as quantity_range, sum(inventory.quantity) as total_quantity from inventory inner join store_sales on inventory.store_id = store_sales.store_id and inventory.product_id = store_sales.product_id group by date_trunc('MONTH', store_sales.sale_date), store_sales.product_id having max(inventory.quantity) - min(inventory.quantity) >= 42;
